    height = 0
    total = 0

    for ch in line:
        if ch == '\\':
            stack.append([height, 0])
            height -= 1
        elif ch == '_':
            if stack:
                stack[-1][1] += 1
            # flat ground, area += 1 but only if inside a basin
        elif ch == '/':
